const input = $input.first().json;
const words = [...(input.words || [])]
  .filter(w =>
    w.word &&
    Number.isFinite(Number(w.start)) &&
    Number.isFinite(Number(w.end)) &&
    Number(w.end) > Number(w.start)
  )
  .sort((a, b) => a.start - b.start);

const config = input.config || {};
const wordsPerLine = Math.max(1, config.wordsPerLine || 4);
const maxChars = config.maxCharsPerLine || 30;
const font = config.font || 'Arial';
const fontSize = config.fontSize || 70;

// Cores ASS no formato AABBGGRR.
const baseColor = config.baseColor || '&H00FFFFFF';
const highlightColor = config.highlightColor || '&H0000D7FF';
const outlineColor = '&H00101010';

function time(seconds) {
  const totalCs = Math.max(0, Math.round(seconds * 100));
  const h = Math.floor(totalCs / 360000);
  const m = Math.floor(totalCs / 6000) % 60;
  const s = Math.floor(totalCs / 100) % 60;
  const cs = totalCs % 100;

  return `${h}:${String(m).padStart(2, '0')}:` +
    `${String(s).padStart(2, '0')}.` +
    `${String(cs).padStart(2, '0')}`;
}

function cleanWord(value) {
  return String(value)
    .replace(/[{}\\]/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

function escapeAssColor(value) {
  return /^&H[0-9A-F]{8}$/i.test(value)
    ? value
    : '&H00FFFFFF';
}

function splitGroups(list, maxWords, maxLength) {
  const groups = [];
  let group = [];
  let length = 0;

  for (const word of list) {
    const text = cleanWord(word.word);
    const extra = text.length + (group.length ? 1 : 0);

    if (
      group.length &&
      (group.length >= maxWords || length + extra > maxLength)
    ) {
      groups.push(group);
      group = [];
      length = 0;
    }

    group.push(word);
    length += text.length + (group.length > 1 ? 1 : 0);

    // Não deixar pontuação iniciar um novo grupo.
    if (/[.!?]$/.test(text)) {
      groups.push(group);
      group = [];
      length = 0;
    }
  }

  if (group.length) groups.push(group);
  return groups;
}

const safeFont = String(font).replace(/[{},\\]/g, '');
const safeBase = escapeAssColor(baseColor);
const safeHighlight = escapeAssColor(highlightColor);

let assContent = `[Script Info]
Title: Timed Dynamic Lyrics
ScriptType: v4.00+
PlayResX: 1080
PlayResY: 1920
WrapStyle: 2
ScaledBorderAndShadow: yes

[V4+ Styles]
Format: Name, Fontname, Fontsize, PrimaryColour, SecondaryColour, OutlineColour, BackColour, Bold, Italic, Underline, StrikeOut, ScaleX, ScaleY, Spacing, Angle, BorderStyle, Outline, Shadow, Alignment, MarginL, MarginR, MarginV, Encoding
Style: Default,${safeFont},${fontSize},${safeHighlight},${safeBase},${outlineColor},&H80000000,1,0,0,0,100,100,0,0,1,4,2,2,60,60,170,1

[Events]
Format: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text
`;

const groups = splitGroups(words, wordsPerLine, maxChars);

for (const group of groups) {
  const groupStart = Number(group[0].start);
  const groupEnd = Number(group[group.length - 1].end);

  if (groupEnd <= groupStart) continue;

  const styledWords = group.map((word, index) => {
    const text = cleanWord(word.word);
    const start = Number(word.start);
    const end = Number(word.end);

    // Karaoke: tempos relativos ao início do evento ASS.
    const offsetCs = Math.max(
      0,
      Math.round((start - groupStart) * 100)
    );

    const durationCs = Math.max(
      1,
      Math.round((end - start) * 100)
    );

    // Pequeno pop no começo da palavra.
    const popIn = offsetCs;
    const popPeak = offsetCs + 8;
    const popOut = offsetCs + 18;

    const pop = config.popAnimation === false
      ? ''
      : `\\t(${popIn},${popPeak},\\fscx112\\fscy112)` +
        `\\t(${popPeak},${popOut},\\fscx100\\fscy100)`;

    // \kt posiciona o início real do karaokê.
    // \kf preenche a palavra ao longo da duração cantada.
    return (
      `{\\kt${offsetCs}\\kf${durationCs}${pop}}` +
      `${text}`
    );
  }).join(' ');

  assContent +=
    `Dialogue: 0,${time(groupStart)},${time(groupEnd)},` +
    `Default,,0,0,0,,${styledWords}\n`;
}

return {
  json: {
    assContent,
    metadata: {
      style: 'timed-dynamic-lyrics',
      wordCount: words.length,
      groupCount: groups.length
    }
  }
};

const input = $input.first().json;
const words = input.words;
const config = input.config || {};

const wordsPerLine = config.wordsPerLine || 3;
const maxChars = config.maxCharsPerLine || 22;

// CORREÇÃO 1: Fonte mais robusta por padrão
const font = config.font || 'Roboto'; 
const fontSize = config.fontSize || 72; // Um pouco maior para impacto
const baseColor = config.baseColor || '&H00FFFFFF';
const highlightColor = config.highlightColor || '&H0000D7FF';
const outlineColor = config.outlineColor || '&H00000000';

// CORREÇÃO 2: Contorno e sombra mais fortes para não parecer "fino"
const outline = config.outline ?? 4; 
const shadow = config.shadow ?? 2; 

const videoWidth = config.videoWidth || 1080;
const videoHeight = config.videoHeight || 1920;
const positionY = config.positionY || Math.round(videoHeight * 0.72);

const zoomScale = config.zoomScale || 118;
const zoomInMs = config.zoomInMs || 80;
const zoomOutMs = config.zoomOutMs || 100;

const minWordDuration = config.minWordDuration || 0.04;
const gapTolerance = config.gapTolerance ?? 0.30;

function assTime(seconds) {
  const totalCs = Math.max(0, Math.round(seconds * 100));
  const h = Math.floor(totalCs / 360000);
  const m = Math.floor((totalCs % 360000) / 6000);
  const s = Math.floor((totalCs % 6000) / 100);
  const cs = totalCs % 100;
  return `${h}:${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}.${String(cs).padStart(2, '0')}`;
}

function cleanWord(value) {
  return String(value ?? '')
    .replace(/[{}\\]/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

function assColor(color) {
  const hex = String(color).replace(/^&H/i, '').replace(/&$/, '');
  const six = hex.length >= 6 ? hex.slice(-6) : 'FFFFFF';
  return `&H${six}&`;
}

function estimateWidth(text, size) {
  let units = 0;
  for (const char of text) {
    if (/[ilíìîï!.,:;'|]/i.test(char)) units += 0.28;
    else if (/[mwMW@%&]/.test(char)) units += 0.88;
    else if (/[A-ZÁÉÍÓÚÂÊÔÃÕÇ]/.test(char)) units += 0.66;
    else if (/[0-9]/.test(char)) units += 0.56;
    else units += 0.53;
  }
  return units * size;
}

function makeGroups(list) {
  const groups = [];
  let current = [];

  for (const word of list) {
    if (!word || !cleanWord(word.word)) continue;

    const item = {
      word: cleanWord(word.word),
      start: Number(word.start),
      end: Number(word.end),
    };

    if (!Number.isFinite(item.start) || !Number.isFinite(item.end) || item.end <= item.start) {
      continue;
    }

    const previous = current[current.length - 1];
    const candidateChars = current.reduce((sum, w) => sum + w.word.length, 0) + item.word.length;
    const gap = previous ? item.start - previous.end : 0;

    const shouldBreak =
      current.length >= wordsPerLine ||
      candidateChars > maxChars ||
      (previous && gap > gapTolerance);

    if (shouldBreak && current.length) {
      groups.push(current);
      current = [];
    }
    current.push(item);
  }
  if (current.length) groups.push(current);
  return groups;
}

function layoutGroup(group) {
  // CORREÇÃO 3: Reduzido de 0.24 para 0.12. Aproxima as palavras sem colidir.
  const gapPx = fontSize * 0.12; 

  const widths = group.map(item => estimateWidth(item.word, fontSize));
  const totalWidth = widths.reduce((sum, width) => sum + width, 0) + gapPx * Math.max(0, group.length - 1);

  const availableWidth = videoWidth * 0.92;
  const fitScale = Math.min(100, (availableWidth / totalWidth) * 100);
  const scaleFactor = fitScale / 100;

  const scaledWidths = widths.map(width => width * scaleFactor);
  const scaledGap = gapPx * scaleFactor;

  const fittedTotal = scaledWidths.reduce((sum, width) => sum + width, 0) + scaledGap * Math.max(0, group.length - 1);
  let x = (videoWidth - fittedTotal) / 2;

  return group.map((item, index) => {
    const width = scaledWidths[index];
    const centerX = Math.round(x + width / 2);
    const result = { ...item, x: centerX, fitScale: Math.round(fitScale) };
    x += width + scaledGap;
    return result;
  });
}

function dialogue(layer, start, end, tags, text) {
  if (end - start < 0.005) return '';
  return `Dialogue: ${layer},${assTime(start)},${assTime(end)},Default,,0,0,0,,{${tags}}${text}\n`;
}

const groups = makeGroups(words);
let events = '';

const baseInline = assColor(baseColor);
const highlightInline = assColor(highlightColor);
const styleBase = String(baseColor).startsWith('&H') ? baseColor : '&H00FFFFFF';
const styleHighlight = String(highlightColor).startsWith('&H') ? highlightColor : '&H0000D7FF';
const styleOutline = String(outlineColor).startsWith('&H') ? outlineColor : '&H00000000';

const header = `[Script Info]
Title: Dynamic Karaoke Bold
ScriptType: v4.00+
WrapStyle: 2
ScaledBorderAndShadow: yes
PlayResX: ${videoWidth}
PlayResY: ${videoHeight}

[V4+ Styles]
Format: Name, Fontname, Fontsize, PrimaryColour, SecondaryColour, OutlineColour, BackColour, Bold, Italic, Underline, StrikeOut, ScaleX, ScaleY, Spacing, Angle, BorderStyle, Outline, Shadow, Alignment, MarginL, MarginR, MarginV, Encoding
Style: Default,${font},${fontSize},${styleBase},${styleHighlight},${styleOutline},&H80000000,1,0,0,0,100,100,0,0,1,${outline},${shadow},5,20,20,20,1

[Events]
Format: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text
`;

for (const group of groups) {
  const laidOut = layoutGroup(group);
  const groupStart = Math.max(0, group[0].start);
  const groupEnd = group[group.length - 1].end;

  for (const item of laidOut) {
    const start = Math.max(groupStart, item.start);
    const end = Math.min(groupEnd, item.end);
    if (end <= start) continue;

    const durationMs = Math.round((end - start) * 1000);
    const inMs = Math.min(zoomInMs, Math.floor(durationMs * 0.35));
    const outMs = Math.min(zoomOutMs, Math.floor(durationMs * 0.35));
    const canZoom = durationMs >= 180 && inMs >= 1 && outMs >= 1 && zoomScale > 100;
    const zoomedScale = Math.round(item.fitScale * (canZoom ? zoomScale : 100) / 100);

    const baseTags = `an5\\pos(${item.x},${positionY})\\fn${font}\\fs${fontSize}\\fscx${item.fitScale}\\fscy100\\bord${outline}\\shad${shadow}\\1c${baseInline}`;

    if (start > groupStart) {
      events += dialogue(0, groupStart, start, baseTags, item.word);
    }

    let activeTags = `an5\\pos(${item.x},${positionY})\\fn${font}\\fs${fontSize}\\fscx${item.fitScale}\\fscy100\\bord${outline}\\shad${shadow}\\1c${highlightInline}`;
    if (canZoom) {
      const zoomOutStart = Math.max(inMs, durationMs - outMs);
      activeTags += `\\t(0,${inMs},\\fscx${zoomedScale}\\fscy${zoomScale})\\t(${zoomOutStart},${durationMs},\\fscx${item.fitScale}\\fscy100)`;
    }

    events += dialogue(1, start, end, activeTags, item.word);

    if (end < groupEnd) {
      events += dialogue(0, end, groupEnd, baseTags, item.word);
    }
  }
}

return {
  json: {
    assContent: header + events,
    wordCount: words.length,
    groupCount: groups.length,
  },
};

