function formatTime(seconds) {
  const h = Math.floor(seconds / 3600);
  const m = Math.floor((seconds % 3600) / 60);
  const s = Math.floor(seconds % 60);
  const c = Math.round((seconds % 1) * 100);
  return `${h}:${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}.${c.toString().padStart(2, '0')}`;
}

function smartBreak(text, maxLen) {
  if (text.length <= maxLen) return text;
  const w = text.split(' ');
  const mid = Math.ceil(w.length / 2);
  return `${w.slice(0, mid).join(' ')}\\N${w.slice(mid).join(' ')}`;
}

function getEmoji(text) {
  const t = text.toLowerCase();
  if (t.includes('beijo') || t.includes('boca')) return '💋 ';
  if (t.includes('veneno')) return '🐍 ';
  if (t.includes('cama') || t.includes('preso')) return '🛏️ ';
  if (t.includes('fogo') || t.includes('vício')) return '🔥 ';
  return '';
}

